package app.oncare.personal;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.Robolectric;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import java.util.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=26)
public class DeepMoodTest {
    @Test public void draftAllowsOnlyBoundedExplicitChoices(){Set<String> feelings=new HashSet<>(Arrays.asList(DeepMood.EMOTIONS));feelings.add("injected");Set<String> contexts=new HashSet<>(Arrays.asList(DeepMood.CONTEXTS));contexts.add("unknown");String text=DeepMood.draft(0,"관계",feelings,contexts,null,"invalid");assertTrue(text.contains("섞인 감정: 불안 · 서운함 · 외로움"));assertTrue(text.contains("상황: 연락 · 관계"));assertFalse(text.contains("injected"));assertFalse(text.contains("unknown"));assertFalse(text.contains("지금 에너지:"));assertTrue(text.length()<2000);}
    @Test public void missingAndInvalidIntensityAreOmittedButZeroIsKept(){String text=DeepMood.draft(0,"자유롭게",Collections.emptySet(),Collections.emptySet(),null,"선택 안 함");assertFalse(text.contains("강도:"));assertFalse(text.contains("섞인 감정:"));assertTrue(DeepMood.draft(0,"자유롭게",Collections.emptySet(),Collections.emptySet(),0,"중간").contains("강도: 0/10"));assertFalse(DeepMood.draft(0,"자유롭게",Collections.emptySet(),Collections.emptySet(),11,"중간").contains("강도:"));}
    @Test public void themeFallbackAndLetterBounds(){assertEquals("미드나잇",DeepMood.style("invalid"));assertEquals("라일락",DeepMood.style("라일락"));assertEquals(DeepMind.PROMPTS.length,DeepMind.TEMPLATES.length);assertTrue(DeepMood.draft(100,"외로움",Collections.emptySet(),Collections.emptySet(),null,"선택 안 함").contains("이 편지를 보내지 않고"));}
    @Test public void chipLimitsAndThemeChangesPreserveUnsavedChoices(){var controller=Robolectric.buildActivity(CareActivity.class);CareActivity a=controller.get();a.getSharedPreferences("app-preferences",0).edit().clear().putBoolean("deep-mind",true).commit();controller.setup();a.tab=1;a.render();int before=a.entries.size();for(String item:new String[]{"불안","서운함","외로움","분노"})find(a.page,"deep-mood-emotion-"+item).performClick();assertEquals(3,a.deepMoodDraft.emotions.size());assertFalse(a.deepMoodDraft.emotions.contains("분노"));find(a.page,"deep-mood-style-라일락").performClick();assertEquals(3,a.deepMoodDraft.emotions.size());assertEquals("라일락",a.getSharedPreferences("app-preferences",0).getString("deep-mind-style",""));find(a.page,"deep-mind-write").performClick();assertEquals(before,a.entries.size());controller.pause().stop().destroy();}
    @Test public void reflectionStaysBoundedAndOmitsUnknownAndEmptyAnswers(){Map<String,String> answers=new HashMap<>();for(String label:DeepMood.REFLECTION)answers.put(label,String.join("",Collections.nCopies(200,"💜")));answers.put("injected","unknown-field");String note=DeepMood.draft(3,"관계",Collections.emptySet(),Collections.emptySet(),null,"중간",answers);assertTrue(note.length()<=2000);assertFalse(note.contains("unknown-field"));assertFalse(note.contains("�"));assertTrue(note.contains("지키고 싶은 선:"));assertFalse(DeepMood.draft(0,"자유롭게",Collections.emptySet(),Collections.emptySet(),null,"선택 안 함",Collections.singletonMap(DeepMood.REFLECTION[0],"  ")).contains("[조금 더 깊이"));}
    @Test public void reflectionSurvivesThemeAndReachesEditableDraftWithoutSaving(){var controller=Robolectric.buildActivity(CareActivity.class);CareActivity a=controller.get();a.getSharedPreferences("app-preferences",0).edit().putBoolean("deep-mind",true).commit();controller.setup();a.tab=1;a.render();int before=a.entries.size();find(a.page,"deep-reflection-expand").performClick();((android.widget.EditText)find(a.page,"deep-reflection-0")).setText("답장이 늦었다");find(a.page,"deep-mood-style-로즈").performClick();assertEquals("답장이 늦었다",a.deepMoodDraft.reflection.get(DeepMood.REFLECTION[0]));find(a.page,"deep-mind-write").performClick();android.app.Dialog dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();android.widget.EditText note=(android.widget.EditText)find(dialog.getWindow().getDecorView(),"record-note");assertTrue(note.getText().toString().contains("실제로 있었던 일: 답장이 늦었다"));assertEquals(before,a.entries.size());dialog.dismiss();find(a.page,"deep-reflection-clear").performClick();assertTrue(a.deepMoodDraft.reflection.isEmpty());assertEquals(before,a.entries.size());controller.pause().stop().destroy();}
    @Test public void reviewRemainsOptionalAndBounded(){Map<String,String> values=new HashMap<>();for(String key:DeepMood.REFLECTION)values.put(key,String.join("",Collections.nCopies(200,"💜")));for(String key:DeepMood.REVIEW)values.put(key,String.join("",Collections.nCopies(200,"💜")));values.put(DeepMood.AFTER,"0");String note=DeepMood.draft(3,"관계",Collections.emptySet(),Collections.emptySet(),8,"중간",values);assertTrue(note.length()<=2000);assertTrue(note.contains("돌아본 감정 강도: 0/10"));values.put(DeepMood.AFTER,"11");assertFalse(DeepMood.answers(values).containsKey(DeepMood.AFTER));}
    @Test public void localSlotRoundTripCorruptionAndRemovalPreserveCurrentInput()throws Exception{CareActivity a=Robolectric.buildActivity(CareActivity.class).get();Map<String,String> current=new HashMap<>();current.put(DeepMood.REVIEW[0],"산책");current.put(DeepMood.AFTER,"0");DeepReview.save(a,current);assertEquals(current,DeepReview.load(a));try(java.io.FileOutputStream stream=new java.io.FileOutputStream(DeepReview.file(a).getBaseFile())){stream.write("invalid".getBytes(java.nio.charset.StandardCharsets.UTF_8));}try{DeepReview.load(a);fail("corrupt draft accepted");}catch(org.json.JSONException expected){}assertEquals("산책",current.get(DeepMood.REVIEW[0]));DeepReview.remove(a);assertFalse(DeepReview.file(a).getBaseFile().exists());}
    @Test public void shortWritingUsesOnlyKnownFocus(){assertTrue(DeepMind.shortTemplate("외로움").contains("오늘 살펴볼 마음: 외로움"));assertFalse(DeepMind.shortTemplate("injected").contains("injected"));assertTrue(DeepMind.shortTemplate("관계").length()<500);assertNotEquals(DeepMind.starter("불안"),DeepMind.starter("외로움"));}
    @Test public void rememberedTopicClampsWithoutLosingCurrentText(){assertEquals(0,DeepMind.promptIndex(Integer.MIN_VALUE));assertEquals(DeepMind.PROMPTS.length-1,DeepMind.promptIndex(Integer.MAX_VALUE));var controller=Robolectric.buildActivity(CareActivity.class);CareActivity a=controller.get();a.getSharedPreferences("app-preferences",0).edit().putBoolean("deep-mind",true).putInt("deep-mind-prompt-v1",3).commit();controller.setup();a.tab=1;a.deepMoodDraft.reflection.put(DeepMood.REFLECTION[0],"내가 쓴 글");a.render();assertEquals(3,a.deepMoodDraft.prompt);assertEquals("내가 쓴 글",a.deepMoodDraft.reflection.get(DeepMood.REFLECTION[0]));controller.pause().stop().destroy();}
    android.view.View find(android.view.View v,String id){if(id.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){android.view.View found=find(g.getChildAt(i),id);if(found!=null)return found;}}return null;}
}
